export type CliTranslationKey = keyof (typeof translations)["en"];

export function getCliLanguage(): CliLanguage {
  const raw = process.env.CHISACODE_LANG?.trim();
  return raw === "en" || raw === "zh-CN" ? raw : DEFAULT_LANGUAGE;
}

export function tCli(
  key: CliTranslationKey,
  vars: Record<string, string | number | null | undefined> = {},
): string {
  const language = getCliLanguage();
  const template = translations[language][key] ?? translations.en[key] ?? key;
  return template.replace(/\{\{(\w+)\}\}/g, (match, name) => {
    const value = vars[name];
    return value === null || value === undefined ? match : String(value);
  });
}
